    except:
        return "-1"

    total = sum(a)

    if total <= 1:
        return "-1"

    min_cost = float('inf')

    for k in range(2, int(total**0.5) + 2):
        if total % k == 0:
            # Calculate cost to make all boxes divisible by k
            cost = 0
            prefix_sum = 0
            possible = True

            for x in a:
                prefix_sum += x
                rem = prefix_sum % k

                # To make prefix_divisible, we need to add or remove chocolates
                # Cost is min(rem, k - rem) but we handle edges properly
                # The cost contribution is based on whether to left-shift or right-shift

                if rem < k:
                    cost += rem
                else:
                    cost += k - rem

            # Add back any final crossover if needed
            if prefix_sum % k == 0:
                # Perfectly divisible
                pass
            elif cost < min_cost:
                min_cost = cost

    # Also check divisors up to total // k
    remaining = True
    for k in range(2, total // min_cost + 2):
        if min_cost != float('inf') and k * k > total:
            break

        if min_cost <= k:
            remaining = False

    for k in range(2, total + 1):
        if k * k > total and k > min_cost:
            break
        if total % k == 0:
            cost = 0
            prefix = 0
            for x in a:
                prefix += x
                r = prefix % k
                if r < 0:
                    r += k
                cost += r
            if cost < min_cost:
                min_cost = cost

    # More careful approach for each divisor
    min_cost = float('inf')
    divisors = set()
    for k in range(2, int(total**0.5) + 2):
        if total % k == 0:
            divisors.add(k)
            if total // k != k:
                divisors.add(total // k)

    if total in divisors:
        divisors.add(total)

    for k in divisors:
        if k <= 1:
            continue
        if total % k == 0:
            cost = 0
            prefix = 0
            for x in a:
                prefix += x
                cost += prefix % k
            if cost < min_cost:
                min_cost = cost

    if min_cost == float('inf'):
        return "-1"

    return str(min_cost)
