    max_sum = t * k
    range_size = max_sum - min_sum + 1

    # dp[shifted_sum] = count of ways to achieve that sum
    # Using shifted index: actual_sum + range_size to map to non-negative index
    def get_dp(turns):
        SIZE = (max_sum - min_sum + range_size)  # Use a safe upper bound
        offset = range_size
        dp = [0] * SIZE
        dp[offset] = 1  # Sum 0 is at index 

