# filename: solution.py
def solution(input_str):
    """
    Find counters to press buttons on such that no counter reaches its target value a[i].

    Args:
        input_str: The entire input as a string

    Returns:
        String with output: first line is k (number of counters), second line is the counter indices
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    graph = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        graph[u].append(v)
        graph[v].append(u)

    a = list(map(int, lines[m + 1].split()))

    # Backtracking for small inputs that need exact match
    if n <= 20:
        x = [0] * (n + 1)

        def calculate_final_val(counter, x, graph):
            result = x[counter]
            for neighbor in graph[counter]:
                result += x[neighbor]
            return result

        def backtrack(idx):
            if idx > n:
                # All counters decided, check validity
                for counter in range(1, n + 1):
                    if calculate_final_val(counter, x, graph) == a[counter - 1]:
                        return False
                return True

            # Try x[idx] = 0
            x[idx] = 0
            if backtrack(idx + 1):
                return True

            # Try x[idx] = 1
            x[idx] = 1
            if backtrack(idx + 1):
                return True

            return False

        if backtrack(1):
            result = [i for i in range(1, n + 1) if x[i] == 1]
            result.sort()
            return f"{len(result)}\n" + " ".join(map(str, result))
        else:
            return "-1\n"

    # Greedy approach for larger inputs
    # For each counter, decide whether to press button based on local constraints
    x = [0] * (n + 1)

    for counter in range(1, n + 1):
        neighbors_sum = sum(x[neighbor] for neighbor in graph[counter] if x[neighbor] == 1)
        current_without_counter = neighbors_sum

        # If counter is not pressed, its value = current_without_counter
        # Check if this violates the constraint
        without_violates = (current_without_counter == a[counter - 1])

        # If counter is pressed, its value = current_without_counter + 1
        # Check if this violates the constraint  
        with_violates = (current_without_counter + 1 == a[counter - 1])

        # Prefer NOT pressing if pressing would violate
        if with_violates and not without_violates:
            x[counter] = 1

    # Check if this assignment is valid
    valid = True
    for counter in range(1, n + 1):
        final_val = x[counter]
        for neighbor in graph[counter]:
            final_val += x[neighbor]
        if final_val == a[counter - 1]:
            valid = False
            break

    if valid:
        result = [i for i in range(1, n + 1) if x[i] == 1]
        result.sort()
        return f"{len(result)}\n" + " ".join(map(str, result))
    else:
        # Try a different heuristic - random or sorted order
        x = [0] * (n + 1)
        order = sorted(range(1, n + 1), key=lambda i: a[i - 1])

        for counter in order:
            neighbors_sum = sum(x[neighbor] for neighbor in graph[counter] if x[neighbor] == 1)
            current_without_counter = neighbors_sum
            without_violates = (current_without_counter == a[counter - 1])
            with_violates = (current_without_counter + 1 == a[counter - 1])

            if with_violates:
                x[counter] = 0
            elif without_violates:
