from typing import List

def is_bitonic(arr: List[int]) -> bool:
    """Check if array is bitonic (increases then decreases)"""
    if len(arr) <= 1:
        return True

    # Find the tallest peak
    peak = 0
    for i in range(1, len(arr)):
        if arr[i] > arr[peak]:
            peak = i

    # Check all increase up to peak
    for i in range(peak):
        if arr[i+1] <= arr[i]:
            return False

    # Check all decrease after peak
    for i in range(peak, len(arr)-1):
        if arr[i+1] >= arr[i]:
            return False

    return True

