import sys
sys.setrecursionlimit(300000)

def solution(data):
    lines = data.strip().split('\n')
    if not lines:
        return "0\n"

    n, m = map(int, lines[0].split())

    if n == 1:
        return "0\n"
    if m == 0:
        return "0\n"

    pre_edges = []
    pre_lookup = {}

    for i in range(1, len(lines)):
        line = lines[i]
        if not line.strip():
            break
        parts = list(map(int, line.strip().split()))
        if len(parts) >= 3:
            u, v, w = parts[0], parts[1], parts[2]
            if u > v:
                u, v = v, u
            pre_edges.append((u-1, v-1, w))
            pre_lookup[(u, v)] = w

    total_edges = n * (n - 1) // 2
    unassigned_count = total_edges - len(pre_edges)

    all_edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if (i, j) in pre_lookup:
                all_edges.append((i, j, pre_lookup[(i, j)]))
            else:
                all_edges.append((i, j, 0))

    all_edges.sort(key=lambda x: x[2])

    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_cost = 0
    unassigned_in_mst = 0
    edges_count = 0

    for u, v, w in all_edges:
        if union(u, v):
            if w == 0:
                unassigned_in_mst += 1
            mst_cost += w
            edges_count += 1
            if edges_count == n - 1:
                break

    xor_sum = 0
    for _, _, w in pre_edges:
        xor_sum ^= w

    remaining_unassigned = unassigned_count - unassigned_in_mst

    if remaining_unassigned > 0 or xor_sum == 0:
        result = mst_cost
    else:
        if xor_sum != 0:
            result = mst_cost + xor_sum
        else:
            result = mst_cost

    return f"{result}\n"

if __name__ == '__main__':
